from textkit.split_identifier import split_identifier


def to_snake_case(name: str) -> str:
    prefix = name[: len(name) - len(name.lstrip("_"))]
    stripped = name.lstrip("_")
    if not stripped:
        return ""

    words = split_identifier(stripped)
    if not words:
        return prefix

    # Re-split each word on camelCase boundaries to handle cases where
    # split_identifier doesn't fully decompose camelCase/PascalCase.
    expanded = []
    for w in words:
        if len(w) == 1:
            # Single character – likely part of an acronym split by
            # split_identifier; keep as-is for merging later.
            expanded.append(w)
        elif w.isupper() or w.islower():
            # All one case (e.g. "SCREAMING" or "screaming") – keep as one token.
            expanded.append(w)
        else:
            # Mixed case – split on camelCase/PascalCase boundaries.
            spaced = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", w)
            spaced = re.sub(r"([A-Z]+)([A-Z][a-z])", r"\1 \2", spaced)
            for part in spaced.split():
                if part:
                    expanded.append(part)

    # Merge consecutive single characters into one token (acronym handling)
    merged = []
    i = 0
    while i < len(expanded):
        if len(expanded[i]) == 1:
            j = i
            while j < len(expanded) and len(expanded[j]) == 1:
                j += 1
            merged.append("".join(expanded[i:j]))
            i = j
        else:
            merged.append(expanded[i])
            i += 1

    if not merged:
        return prefix
    return prefix + "_".join(w.lower() for w in merged)
